/// <summary>
/// API JSON dashboard rèn luyện sinh viên.
/// action=filters — danh sách Khoa / Khóa / Lớp
/// action=data    — dữ liệu biểu đồ từ DASH_StudentEthic_GetData
/// Bộ lọc: yearId, semester, scienceId, courseId, classId, fromDate, toDate
/// </summary>

