function validateFilters(filters) {
    if (!isFilterValueActive(filters.yearId)) {
        return "Vui lòng chọn Năm học.";
    }
    if (!isFilterValueActive(filters.semester)) {
        return "Vui lòng chọn Học kỳ.";
    }
    if (!filters.fromDate) {
        return "Vui lòng chọn Từ ngày.";
    }
    if (!filters.toDate) {
        return "Vui lòng chọn Đến ngày.";
    }
    if (filters.fromDate > filters.toDate) {
        return "Từ ngày không được lớn hơn Đến ngày.";
    }
    return "";
}

